/**
 * sync-standalone.mjs
 * Copy standalone HTML pages from public/ → dist/ so they survive
 * deploys where the full Astro build cannot run (e.g. Directus offline).
 *
 * Usage: node scripts/sync-standalone.mjs
 * Called automatically by `npm run deploy:fast`
 */
import { cpSync, existsSync, mkdirSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');

// Directories under public/ that are standalone (not generated by Astro).
// Add new entries here when you drop a new standalone page into public/.
const STANDALONE_DIRS = [
  'quiz',
  'quiz-vietanh',
];

if (!existsSync(resolve(ROOT, 'dist'))) {
  console.error('ERROR: dist/ does not exist. Run the Astro build first, or deploy from a dist/ that exists.');
  process.exit(1);
}

for (const dir of STANDALONE_DIRS) {
  const src  = resolve(ROOT, 'public', dir);
  const dest = resolve(ROOT, 'dist',   dir);

  if (!existsSync(src)) {
    console.warn(`SKIP: public/${dir} not found`);
    continue;
  }

  mkdirSync(dest, { recursive: true });
  cpSync(src, dest, { recursive: true, force: true });
  console.log(`✓ synced public/${dir} → dist/${dir}`);
}

console.log('sync-standalone done.');
